// Community Q&A
// Forum articles: static, indexable pages generated from the starter topics in lib/seed*.js.
const seedForum = require('./lib/seed'), seedExtra = require('./lib/seed-extra');
const slugify = t => t.toLowerCase().replace(/&/g, ' and ').replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 70).replace(/-$/, '');
const forumCats = seedForum.categories.concat(seedExtra.categories).map(([slug, name, description]) => ({ slug, name, description }));
const forumTopics = seedForum.threads.concat(seedExtra.threads).map(([category, title, body, , pinned]) => ({ category, title, body, pinned, slug: slugify(title) }));
function renderBody(text) {
  return text.split(/\n{2,}/).map(block => {
    const lines = block.split('\n').map(l => l.trim()).filter(Boolean);
    if (lines.length && lines.every(l => /^- /.test(l))) return `<ul>${lines.map(l => `<li>${esc(l.slice(2))}</li>`).join('')}</ul>`;
    if (lines.length && lines.every(l => /^\d+\.\s/.test(l))) return `<ol>${lines.map(l => `<li>${esc(l.replace(/^\d+\.\s/, ''))}</li>`).join('')}</ol>`;
    return lines.map(l => `<p>${esc(l)}</p>`).join('');
  }).join('');
}
const firstPara = t => t.split(/\n{2,}/)[0].replace(/\s+/g, ' ').trim();
const clip = (s, n) => s.length <= n ? s : s.slice(0, n - 1).replace(/\s+\S*$/, '') + '…';
const topicCard = t => `<div class="col-md-6"><a class="card guide-card h-100" href="/forum/${t.slug}/"><div class="card-body p-4"><h3 class="h5">${esc(t.title)}</h3><p class="text-muted">${esc(clip(firstPara(t.body), 140))}</p><span class="more">Read more ${icon('arrow', 'ms-1')}</span></div></a></div>`;
add({
  url: '/forum/', title: 'Bathroom Remodeling & Plumbing Emergency Forum', desc: 'Free guides for Illinois homeowners: what to do about an overflowing toilet or leaking shower, the advantages of tile, 2026 bathroom remodel costs and home value.', crumbs: [['Forum', '/forum/']],
  ld: [{ '@context': 'https://schema.org', '@type': 'CollectionPage', name: 'Budget Bath Solutions Forum', url: site.url + '/forum/' }],
  body: pageHead('Homeowner Forum', 'Straight answers on plumbing emergencies, tile, costs and remodeling in Kane, Kendall, DuPage and DeKalb counties.', [['Forum', '/forum/']]) + `<section class="section"><div class="container"><div class="mb-4"><label for="forum-search" class="form-label visually-hidden">Search the forum</label><input id="forum-search" type="search" class="form-control form-control-lg" placeholder="Search topics, e.g. toilet, tile, cost" data-forum-search><p class="small text-muted mt-2 mb-0" role="status" aria-live="polite" data-forum-count></p></div>${forumCats.map(c => { const ts = forumTopics.filter(t => t.category === c.slug); return ts.length ? `<div class="mb-5" id="${c.slug}"><h2>${esc(c.name)}</h2><p class="text-muted">${esc(c.description)}</p><div class="row g-4">${ts.map(topicCard).join('')}</div></div>` : ''; }).join('')}<p class="text-muted">Want to ask a question? Visit <a href="/community/">Community Q&amp;A</a>.</p></div></section>` + ctaBand('Need help with your bathroom?')
});
for (const t of forumTopics) {
  const cat = forumCats.find(c => c.slug === t.category), url = `/forum/${t.slug}/`;
  const crumbs = [['Forum', '/forum/'], [t.title, url]];
  const related = forumTopics.filter(r => r.category === t.category && r !== t).slice(0, 4);
  const desc = clip(firstPara(t.body), 155);
  add({
    url, title: clip(t.title, 60), desc, crumbs,
    ld: [{ '@context': 'https://schema.org', '@type': 'Article', headline: clip(t.title, 110), description: desc, dateModified: today, author: { '@type': 'Organization', name: site.name }, publisher: { '@id': site.url + '/#business' }, mainEntityOfPage: site.url + url, articleSection: cat ? cat.name : 'Forum' }],
    body: pageHead(esc(t.title), esc(desc), crumbs) + `<section class="section"><div class="container"><div class="row g-5"><div class="col-lg-8 article">${renderBody(t.body)}<div class="callout"><strong>Need a pro?</strong> Our team serves ${areaNames}. ${callUs()} or <a href="/contact/">request a free estimate</a>. Related: <a href="/services/bathroom-remodeling/">bathroom remodeling</a>, <a href="/services/tile-installation/">tile installation</a>, <a href="/homeowner-help/">homeowner guides</a>.</div>${related.length ? `<h2>Related topics</h2><ul>${related.map(r => `<li><a href="/forum/${r.slug}/">${esc(r.title)}</a></li>`).join('')}</ul>` : ''}</div><aside class="col-lg-4"><div class="sticky-lg-top aside-sticky">${projectForm()}</div></aside></div></div></section>`
  });
}

