add({ url: '/about/', title: 'About Budget Bath Solutions', desc: 'Budget Bath Solutions helps homeowners in Kane, Kendall, DuPage and DeKalb counties with bathroom remodeling, tile and home projects.', crumbs: [['About', '/about/']], body: pageHead('About Budget Bath Solutions', 'A local team focused on bathrooms, tile and straightforward service.', [['About', '/about/']]) + `<section class="section"><div class="container"><div class="row g-5"><div class="col-lg-7 article"><h2>Our approach</h2><p>We started with a simple idea: remodeling should be less stressful. That means listening first, explaining options in plain language and doing careful work in your home.</p><h2>What we do</h2><p>Bathroom remodeling and tile installation are our specialty, along with shower and tub remodeling and other home projects. We serve ${areaNames}, Illinois.</p><h2>How we work</h2><ul class="check-list">${['You request a free estimate', 'We talk through your goals and visit your home', 'You receive a written scope and schedule', 'We do the work and walk through it with you'].map(x => `<li>${icon('check')}${x}</li>`).join('')}</ul><p class="mt-4">Want to join us? See <a href="/work-with-us/">Work With Us</a>.</p></div><div class="col-lg-5">${projectForm()}</div></div></div></section>` });
add({ url: '/contact/', title: 'Contact Us & Request a Free Estimate', desc: 'Request a free bathroom remodeling or tile estimate in Kane, Kendall, DuPage or DeKalb county, Illinois. Contact Budget Bath Solutions.', crumbs: [['Contact', '/contact/']], body: pageHead('Contact Us', 'Tell us about your project and we will be in touch to schedule your free estimate.', [['Contact', '/contact/']]) + `<section class="section"><div class="container"><div class="row g-5"><div class="col-lg-7">${projectForm()}</div><div class="col-lg-5"><div class="card card-body p-4 contact-card"><h2 class="h4">Reach us</h2><p>${icon('phone', 'me-1')} ${contactLine()}</p>${site.email ? `<p><a href="mailto:${esc(site.email)}">${esc(site.email)}</a></p>` : ''}<p>${icon('pin', 'me-1')} Serving ${areaNames}, Illinois</p><p class="mb-0">${site.hours}</p></div></div></div></div></section>` });
add({
  url: '/work-with-us/', title: 'Work With Us: Careers & Subcontractor Opportunities', desc: 'Join Budget Bath Solutions. We are looking for tile setters, bathroom remodelers and skilled trades in Kane, Kendall, DuPage and DeKalb counties, IL.', crumbs: [['Work With Us', '/work-with-us/']],
  ld: [{ '@context': 'https://schema.org', '@type': 'WebPage', name: 'Work With Us', url: site.url + '/work-with-us/' }],
  body: pageHead('Work With Us', 'Skilled in tile, remodeling or the trades? Join a team that values quality and communication.', [['Work With Us', '/work-with-us/']]) + `<section class="section"><div class="container"><div class="row g-5"><div class="col-lg-5"><h2>Who we are looking for</h2><ul class="check-list">${['Tile setters and helpers', 'Bathroom remodelers and carpenters', 'Plumbers and electricians', 'Painters and finishers', 'Reliable subcontractors'].map(x => `<li>${icon('check')}${x}</li>`).join('')}</ul><h2 class="mt-5">What you can expect</h2><p>Respect, clear expectations and steady local work. Tell us about your experience and we will be in touch about next steps.</p><p class="text-muted small">Submitting this form does not create an employment or contracting relationship. Positions and pay vary and are not guaranteed.</p><p><a class="btn btn-brass" href="/handyman-application/">Handyman &amp; trades application</a></p><p class="small">Already part of the team? <a href="/employee/">Employee portal</a></p></div><div class="col-lg-7">${form('work', { heading: 'Apply to work with us', note: 'Share a few details and we will follow up if there is a fit.', interestLabel: 'Trade / role', interestOptions: ['Tile setter', 'Tile helper', 'Remodeler / carpenter', 'Plumber', 'Electrician', 'Painter / finisher', 'Other'], messageLabel: 'Your experience, licenses and availability', button: 'Send My Application' })}</div></div></div></section>`
});

// Legal
const legal = (url, title, desc, html) => add({ url, title, desc, crumbs: [[title, url]], body: pageHead(title, `Last updated ${today}`, [[title, url]]) + `<section class="section"><div class="container"><div class="article legal">${html}</div></div></section>` });
legal('/privacy/', 'Privacy Policy', 'How Budget Bath Solutions collects, uses and protects information submitted through this website.', `<p>This policy explains how ${site.name} handles information you provide through this website.</p><h2>Information we collect</h2><p>When you submit a form, we collect the details you enter, such as your name, email, phone, county, project or role details and message. We also keep standard technical information needed to run and secure the site, such as IP address in server logs and rate limiting.</p><h2>How we use it</h2><p>We use your information to respond to your request, provide estimates, evaluate work applications and operate and protect the site. We do not sell your personal information.</p><h2>Customer accounts and photos</h2><p>If you create a free account, we store your name, email, optional phone number, a securely hashed password, and the project requests and photos you send. Photos are stored privately and are visible only to you and our team. Please do not upload images that show people&rsquo;s faces, documents or other sensitive information.</p><h2>Work applications and employees</h2><p>If you apply to work with us, we store the details you submit (such as your trade, experience, availability and references) so we can review your application, and we may delete it when it is no longer needed. If you are hired, our team keeps your employee account, job assignments, hours, payment records, signed contracts and the paperwork you upload, for business, tax and legal record-keeping. These are visible only to you and authorized staff.</p><h2>Documents shared by our team</h2><p>Customer files, photos, receipts and messages we keep for your project are private. They appear in your account only if our team chooses to share them with you.</p><h2>Cookies and analytics</h2><p>When you sign in, we set one essential session cookie to keep you signed in. We do not use advertising trackers. If the site owner turns on the optional visit statistics (off by default), we record the page visited, the referring website name, a device type (phone, tablet or desktop) and an anonymous visitor code that changes every day and cannot be traced back to you. We do not store your IP address for this, we skip visitors who send a Do Not Track or Global Privacy Control signal, and we do not share these statistics with advertisers.</p><h2>Email</h2><p>We send transactional emails such as account confirmation, password resets, and replies to your requests. We do not send marketing email without your permission.</p><h2>Sharing</h2><p>We share information only with service providers who help us run the business, such as Resend, which delivers our email, and where required by law.</p><h2>Retention and security</h2><p>We keep submissions as long as needed to respond and for business records, and we use reasonable safeguards. No method of transmission or storage is completely secure.</p><h2>Your choices</h2><p>You may ask us to access, correct or delete your information by ${callUs()}. Do not send sensitive personal information, such as Social Security or financial account numbers, through the forms.</p><h2>Children</h2><p>This site is not directed to children under 13.</p><h2>Changes</h2><p>We may update this policy and will post the date above.</p>`);
legal('/terms/', 'Terms of Use', 'Terms governing use of the Budget Bath Solutions website.', `<p>By using this website you agree to these terms.</p><h2>General information only</h2><p>Content, including homeowner guides and Q&amp;A, is general information and not professional, legal or engineering advice. Conditions in your home vary. Contact us for advice specific to your project.</p><h2>No contract by website</h2><p>Submitting a form or reading an estimate range does not create a contract. Work is performed only under a separate written agreement.</p><h2>Acceptable use</h2><p>Do not misuse the site, submit false or harmful content, attempt unauthorized access or interfere with its operation.</p><h2>Intellectual property</h2><p>Site content belongs to ${site.name} or its licensors. You may not copy it without permission.</p><h2>Disclaimer and limitation of liability</h2><p>The site is provided &ldquo;as is.&rdquo; To the fullest extent permitted by law, ${site.name} is not liable for damages arising from your use of the site.</p><h2>Governing law</h2><p>These terms are governed by the laws of the State of Illinois.</p><h2>Changes</h2><p>We may update these terms at any time.</p>`);
legal('/accessibility/', 'Accessibility Statement', 'Budget Bath Solutions is committed to making this website usable by everyone, including people with disabilities.', `<p>We want everyone to be able to use this website. We aim to follow the Web Content Accessibility Guidelines (WCAG) 2.2 Level AA.</p><h2>What we do</h2><ul><li>Semantic headings, landmarks and a skip link</li><li>Keyboard-operable navigation and forms with labels</li><li>Sufficient color contrast and responsive layouts</li><li>Respect for reduced-motion preferences</li></ul><h2>Feedback</h2><p>If you have trouble using any part of this site, please ${callUs()} and tell us what happened. We will work to help and fix the issue.</p>`);
add({ url: '/thank-you/', title: 'Thank You', desc: 'Thanks for contacting Budget Bath Solutions.', noindex: true, body: pageHead('Thank you!', 'We received your information and will be in touch soon.') + `<section class="section"><div class="container text-center"><a class="btn btn-brass btn-lg" href="/">Back to Home</a></div></section>` });
add({ url: '/offline/', title: 'You are offline', desc: 'You appear to be offline.', noindex: true, body: pageHead('You are offline', 'Check your connection and try again. This page will work again as soon as you are back online.') + `<section class="section"><div class="container text-center">${phoneHref ? `<p class="lead">Need us now? Call <a href="${phoneHref}">${esc(site.phone)}</a>.</p>` : ''}<a class="btn btn-brass btn-lg" href="/">Try again</a></div></section>` });
add({ url: '/404.html', file: '404.html', title: 'Page Not Found', desc: 'The page you were looking for could not be found.', noindex: true, body: pageHead('Page not found', 'That page does not exist or has moved.') + `<section class="section"><div class="container text-center"><p class="lead">Try one of these instead:</p><div class="d-flex flex-wrap gap-3 justify-content-center"><a class="btn btn-brass btn-lg" href="/">Back to Home</a><a class="btn btn-outline-dark btn-lg" href="/services/">Our Services</a><a class="btn btn-outline-dark btn-lg" href="/homeowner-help/">Homeowner Help</a><a class="btn btn-outline-dark btn-lg" href="/forum/">Forum</a><a class="btn btn-outline-dark btn-lg" href="/contact/">Contact Us</a></div></div></section>` });

