const area = (id, label, rows = 3, required = false, max = 600) => `<div class="col-12"><label for="${id}" class="form-label">${label}${required ? ' <span class="text-danger" aria-hidden="true">*</span>' : ''}</label><textarea class="form-control form-control-lg" id="${id}" name="${id}" rows="${rows}" maxlength="${max}"${required ? ' required' : ''}></textarea></div>`;
