// Customer accounts (rendered by assets/account.js; never indexed)
const acct = (url, title, lead, inner, page) => add({ url, title, desc: `${title} for Budget Bath Solutions customers.`, noindex: true, body: pageHead(title, lead) + `<section class="section"><div class="container"><div class="row justify-content-center"><div class="${['dashboard', 'request', 'admin', 'estimate'].includes(page) ? 'col-lg-10' : 'col-lg-6'}" data-account-page="${page}">${inner}</div></div></div></section>` });
const authForm = ({ api, button, fields, extra = '', redirect = '' }) => `<form class="lead-form card card-body p-4 p-lg-5 shadow-lg" data-auth data-api="${api}"${redirect ? ` data-redirect="${redirect}"` : ''} novalidate><div class="row g-3">${fields}<div class="col-12"><button class="btn btn-brass btn-lg w-100" type="submit">${button}</button><div class="form-status mt-3" role="status" aria-live="polite"></div></div></div>${extra}</form>`;
const emailField = field('email', 'Email', { type: 'email', required: true, col: 'col-12', autocomplete: 'email' });
const passField = (label, auto) => field('password', label, { type: 'password', required: true, col: 'col-12', autocomplete: auto, attrs: ' minlength="10" maxlength="200"', hint: auto === 'new-password' ? 'At least 10 characters.' : '' });
const projectTypes = services.map(s => s.name).concat(['Not sure yet']);
const timelines = ['As soon as possible', 'Within 1-3 months', '3-6 months', 'Just exploring'];
const budgets = ['Under $5,000', '$5,000-$10,000', '$10,000-$20,000', '$20,000+', 'Not sure yet'];
acct('/account/login/', 'Sign In', 'Welcome back. Sign in to manage your project requests.', authForm({ api: '/api/auth/login', button: 'Sign In', redirect: '/account/', fields: emailField + passField('Password', 'current-password'), extra: '<p class="mt-4 mb-0 text-center"><a href="/account/forgot-password/">Forgot your password?</a> &middot; <a href="/account/register/">Create a free account</a></p>' }), 'login');
acct('/account/register/', 'Create Your Free Account', 'Send us photos and tell us what you are looking for. It only takes a minute.', authForm({ api: '/api/auth/register', button: 'Create Free Account', fields: field('name', 'Full name', { required: true, col: 'col-12', autocomplete: 'name' }) + emailField + field('phone', 'Phone (optional)', { type: 'tel', col: 'col-12', autocomplete: 'tel' }) + passField('Password', 'new-password') + '<div class="col-12"><div class="form-check"><input class="form-check-input" type="checkbox" id="consent" name="consent" required><label class="form-check-label" for="consent">I agree to the <a href="/terms/" target="_blank" rel="noopener noreferrer">Terms of Use</a> and <a href="/privacy/" target="_blank" rel="noopener noreferrer">Privacy Policy</a>.</label><div class="invalid-feedback">Please agree to continue.</div></div></div>', extra: '<p class="mt-4 mb-0 text-center">Already have an account? <a href="/account/login/">Sign in</a></p>' }), 'register');
acct('/account/forgot-password/', 'Forgot Password', 'Enter your email and we will send you a link to reset it.', authForm({ api: '/api/auth/forgot', button: 'Send Reset Link', fields: emailField }), 'forgot');
acct('/account/reset-password/', 'Choose a New Password', 'Pick a new password for your account.', authForm({ api: '/api/auth/reset', button: 'Update Password', redirect: '/account/login/', fields: passField('New password', 'new-password') }), 'reset');
acct('/account/verify/', 'Confirm Your Email', 'One moment while we confirm your email address.', '<div class="card card-body p-4 p-lg-5 text-center"><div class="form-status" role="status" aria-live="polite">Confirming...</div><p class="mt-4 mb-0"><a class="btn btn-brass" href="/account/login/">Sign In</a></p></div>', 'verify');
acct('/account/', 'My Account', 'Your project requests, photos and messages to our team.', '<div id="account-root" class="form-status" role="status" aria-live="polite">Loading...</div>', 'dashboard');
acct('/account/new/', 'New Project Request', 'Tell us what you are looking for and add photos of your space.', `<form class="lead-form card card-body p-4 p-lg-5 shadow-lg" data-request-form novalidate><div class="row g-3">${field('title', 'Project title', { required: true, col: 'col-12', attrs: ' maxlength="120" placeholder="e.g. Primary bath remodel"' })}${select('projectType', 'Project type', projectTypes)}<div class="col-12 col-md-6"><label for="category" class="form-label">What kind of help?</label><select class="form-select form-select-lg" id="category" name="category"><option value="">Select (optional)</option></select></div>${select('location', 'County', counties.map(c => c.name).concat(['Other / not sure']))}${select('timeline', 'Timeline', timelines, false)}${select('budget', 'Budget range', budgets, false)}<div class="col-12"><label for="description" class="form-label">What are you looking for? <span class="text-danger" aria-hidden="true">*</span></label><textarea class="form-control form-control-lg" id="description" name="description" rows="5" minlength="10" maxlength="4000" required></textarea><div class="invalid-feedback">Please describe your project (at least 10 characters).</div></div><div class="col-12"><label for="photos" class="form-label">Photos and videos (optional)</label><input class="form-control form-control-lg" id="photos" type="file" accept="image/jpeg,image/png,image/webp,video/mp4,video/quicktime,video/webm" multiple aria-describedby="photos-hint"><div data-file-summary class="small mt-2" aria-live="polite"></div><div id="photos-hint" class="form-text">Up to 10 files: photos (JPG, PNG or WebP, 8 MB each) or short videos (MP4, MOV or WebM, 100 MB each). Walk us around the room. Files are private and only visible to you and our team.</div></div><div class="col-12"><button class="btn btn-brass btn-lg w-100" type="submit">Send to Budget Bath Solutions</button><div class="form-status mt-3" role="status" aria-live="polite"></div></div></div></form>`, 'new');
acct('/account/estimate/', 'Estimate', 'Review, sign and pay your estimate.', '<div id="account-root" class="form-status" role="status" aria-live="polite">Loading...</div>', 'estimate');
acct('/account/request/', 'Project Request', 'Details and photos for your request.', '<div id="account-root" class="form-status" role="status" aria-live="polite">Loading...</div>', 'request');
acct('/account/admin/', 'Customer Requests', 'Submitted project requests and photos (staff only).', '<div id="account-root" class="form-status" role="status" aria-live="polite">Loading...</div>', 'admin');

// Write
fs.rmSync(out, { recursive: true, force: true });
const write = (rel, data) => { const f = path.join(out, rel); fs.mkdirSync(path.dirname(f), { recursive: true }); fs.writeFileSync(f, data); };
for (const p of pages) write(p.file || (p.url === '/' ? 'index.html' : p.url.slice(1) + 'index.html'), layout(p).replace(/loading="lazy"/g, 'loading="lazy" decoding="async" fetchpriority="low"').replace('<img src="/favicon.svg" alt=""', '<img src="/favicon.svg" alt="" fetchpriority="high"'));
const indexable = pages.filter(p => !p.noindex);
write('sitemap.xml', `<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9" xmlns:image="http://www.google.com/schemas/sitemap-image/1.1">\n${indexable.map(p => `<url><loc>${site.url}${p.url}</loc><lastmod>${today}</lastmod>${p.url === '/' ? `<image:image><image:loc>${site.url}/og-image.png</image:loc></image:image>` : ''}</url>`).join('\n')}\n</urlset>\n`);
write('robots.txt', `User-agent: *\nAllow: /\nDisallow: /api/\nDisallow: /admin/\nDisallow: /account/\nDisallow: /employee/\nDisallow: /estimator/\nDisallow: /thank-you/\n\nSitemap: ${site.url}/sitemap.xml\n`);
write('site.webmanifest', JSON.stringify({ name: site.name, short_name: 'Budget Bath', start_url: '/', display: 'browser', background_color: '#f6f1e9', theme_color: '#12302f', icons: [{ src: '/favicon.svg', sizes: 'any', type: 'image/svg+xml' }] }));
write('.well-known/security.txt', `Contact: ${site.email ? 'mailto:' + site.email : site.url + '/contact/'}\nExpires: ${new Date(Date.now() + 365 * 864e5).toISOString()}\nCanonical: ${site.url}/.well-known/security.txt\nPreferred-Languages: en\n`);
// og-card.html is only the source for rendering og-image.png; it is not published.
for (const f of fs.readdirSync(path.join(__dirname, 'assets')).filter(f => f !== 'og-card.html')) fs.cpSync(path.join(__dirname, 'assets', f), path.join(out, f), { recursive: true });
const bs = path.join(__dirname, 'node_modules/bootstrap/dist');
fs.mkdirSync(path.join(out, 'vendor'), { recursive: true });
fs.copyFileSync(path.join(bs, 'css/bootstrap.min.css'), path.join(out, 'vendor/bootstrap.min.css'));
fs.copyFileSync(path.join(bs, 'js/bootstrap.bundle.min.js'), path.join(out, 'vendor/bootstrap.bundle.min.js'));
console.log(`Built ${pages.length} pages into dist/`);
